def public_browser_html(*, remote_admin_enabled: bool = False) -> bytes:
    page = _legacy_public_browser_html(remote_admin_enabled=remote_admin_enabled)
    marker = b"</body>"
    extension = _public_extension(remote_admin_enabled).encode("utf-8")
    page = page.replace(marker, extension + marker, 1) if marker in page else page + extension
    return _official_theme(page)


def admin_login_html() -> bytes:
    page = _legacy_admin_login_html()
    page = page.replace(b'class="login-intro"><img src="/assets/icon.webp"', b'class="login-intro"><img src="/assets/platforms/remote-login.svg"', 1)
    page = page.replace(
        b'<label>World Name<input class="field" id="world" autocomplete="organization" required></label>',
        b'<label>World Name<select class="field" id="world" autocomplete="organization" required><option value="">Loading hosted profiles...</option></select></label>',
        1,
    )
    page = page.replace(
        b"world_name:document.getElementById('world').value,username:",
        b"world_name:document.getElementById('world').selectedOptions[0]?.dataset.worldName||document.getElementById('world').value,profile_id:document.getElementById('world').value,username:",
        1,
    )
    script = b'''<script id="dws-prefill-world">(async()=>{const select=document.getElementById('world'),message=document.getElementById('message'),wanted=new URLSearchParams(location.search).get('world')||'';if(!select)return;try{const response=await fetch('/api/v1/admin/profiles',{cache:'no-store',headers:{Accept:'application/json'}}),data=await response.json();if(!response.ok)throw Error(data.error||'Hosted profiles are unavailable');const profiles=Array.isArray(data.profiles)?data.profiles:[];select.replaceChildren(new Option(profiles.length?'Select a hosted World':'No hosted World profiles are available',''));for(const profile of profiles){const name=String(profile.world_name||'').trim(),id=String(profile.profile_id||'').trim();if(!name||!id)continue;const option=new Option(name+(profile.running?' (running)':''),id);option.dataset.worldName=name;select.appendChild(option)}const matched=profiles.find(profile=>String(profile.world_name||'').localeCompare(wanted,undefined,{sensitivity:'accent'})===0),preferred=matched||profiles.find(profile=>profile.running)||profiles[0];if(preferred)select.value=String(preferred.profile_id||'');if(select.value)document.getElementById('account')?.focus()}catch(error){select.replaceChildren(new Option(wanted||'Hosted profiles unavailable',''));if(message)message.textContent=error.message||String(error)}})();</script>'''
    login_only = b'''<style id="dws-login-only">.login-wrap{width:min(520px,calc(100% - 28px))!important;grid-template-columns:1fr!important;gap:0!important}.login-intro{display:none!important}.login-panel{width:100%;box-sizing:border-box}.login-note{display:none!important}</style>'''
    page = page.replace(b"</head>", login_only + b"</head>", 1)
    return _official_theme(page.replace(b"</body>", script + b"</body>", 1))


def remote_admin_html() -> bytes:
    page = _legacy_remote_admin_html()
    marker = b"</body>"
    extension = _remote_admin_extension() + _REMOTE_ADMIN_WORKSPACE_EXTENSION
    page = page.replace(marker, extension + marker, 1) if marker in page else page + extension
    return _official_theme(page)


def detail_html(world_id: str) -> bytes:
    page = _legacy_detail_html(world_id)
    # Public specs/network evidence remain useful. Raw debug dumps/buttons do not.
    cleanup = b'''<style>.all-world-metadata{display:none!important}.detail-actions a[href^="/api/v1/worlds/"]{display:none!important}</style>'''
    return _official_theme(page.replace(b"</head>", cleanup + b"</head>", 1))
